// Build-time data layer. JSON in /data is bundled at compile time and validated here;
// invalid data throws during `next build`, so a broken file never reaches production.
//
// data/episodes.json is generated by `yarn fetch-episodes` (raw Spotify data). Everything
// else (season/episode codes, groups, Herohero CTA) is derived here, so changing the rules
// in seasons.json / groups.json never needs a re-fetch.
import episodesJson from "../../data/episodes.json";
import groupsJson from "../../data/groups.json";
import profileJson from "../../data/profile.json";
import seasonsJson from "../../data/seasons.json";
import sponsorshipJson from "../../data/sponsorship.json";

interface RawEpisode {
  id: string;
  name: string;
  description: string;
  releaseDate: string;
  durationMs: number;
  image: string | null;
}

export interface Episode {
  spotifyId: string;
  /** "S16E05", "S07" (season special), "Changelog #3", or null for unmatched specials */
  code: string | null;
  /** Title without the code prefix, e.g. "Jaroslav Rychna - Bankovní core systémy a integrace" */
  title: string;
  /** Part of the title before the first " - " for season episodes (the guest) */
  guest: string | null;
  description: string;
  releaseDate: string; // ISO yyyy-mm-dd
  durationMinutes: number;
  image: string | null;
  spotifyUrl: string;
  /** Set when the full episode is on Herohero (CTA to the profile page) */
  heroheroUrl: string | null;
}

export interface SeasonEpisode extends Episode {
  number: number;
}

export interface Partner {
  name: string;
  url: string;
  logo: string;
}

export interface Season {
  number: number;
  episodes: SeasonEpisode[]; // E01 first
  specials: Episode[]; // "Sxx - …" titles, oldest first
  plannedEpisodes: number;
  /** Planned but not yet released episodes ("Připravujeme" placeholders) */
  upcoming: number;
  isRunning: boolean;
  /** Year the season started (first release), used by the series navigator timeline */
  year: number;
  guests: string[];
  youtubePlaylist: string | null;
}

export interface Group {
  id: string;
  title: string;
  description: string;
  /** Series navigator chip: Lucide icon name from src/components/icon.tsx + short label */
  chip: { icon: string; label: string };
  /** Supporter-only content: full episodes on Herohero */
  herohero: boolean;
  episodes: Episode[]; // newest first
  youtubePlaylist: string | null;
}

export interface Profile {
  tagline: string;
  subtitle: string;
  hashtag: string;
  about: string;
  hosts: { name: string; email: string }[];
  platforms: { spotify: string; apple: string; youtube: string; herohero: string; bluesky: string };
  company: { name: string; address: string; ico: string; registry: string };
}

interface SeasonConfig {
  number: number;
  plannedEpisodes?: number;
  youtubePlaylist?: string;
}

interface GroupConfig {
  id: string;
  prefix?: string;
  fallback?: boolean;
  title: string;
  description: string;
  chip: { icon: string; label: string };
  herohero: boolean;
  youtubePlaylist?: string;
}

function fail(file: string, message: string): never {
  throw new Error(`[data/${file}] ${message}`);
}

export const profile: Profile = profileJson;

const rawEpisodes = episodesJson.episodes as RawEpisode[];
if (rawEpisodes.length === 0) fail("episodes.json", "no episodes, run `yarn fetch-episodes`");

// ---- Groups -------------------------------------------------------------------------------

const groupConfigs = groupsJson.groups as GroupConfig[];
groupConfigs.forEach((g, i) => {
  if (!g.id || !g.title) fail("groups.json", `groups[${i}]: id and title are required`);
  if (!g.chip?.icon || !g.chip?.label) fail("groups.json", `groups[${i}] "${g.id}": chip.icon and chip.label are required`);
  if (!g.prefix === !g.fallback) fail("groups.json", `groups[${i}] "${g.id}": set exactly one of "prefix" or "fallback": true`);
});
if (new Set(groupConfigs.map((g) => g.id)).size !== groupConfigs.length) fail("groups.json", "group ids must be unique");
const fallbackGroups = groupConfigs.filter((g) => g.fallback);
if (fallbackGroups.length > 1) fail("groups.json", "only one group can be the fallback");

// ---- Seasons config -----------------------------------------------------------------------

const seasonConfigs = new Map((seasonsJson.seasons as SeasonConfig[]).map((s) => [s.number, s]));
const isUrl = (v: string | undefined) => v === undefined || /^https:\/\//.test(v);
seasonConfigs.forEach((s) => {
  if (!isUrl(s.youtubePlaylist)) fail("seasons.json", `season ${s.number}: youtubePlaylist must be an https URL`);
});
groupConfigs.forEach((g) => {
  if (!isUrl(g.youtubePlaylist)) fail("groups.json", `group "${g.id}": youtubePlaylist must be an https URL`);
});

// ---- Classification -----------------------------------------------------------------------

const SEASON_EPISODE = /^S(\d+)E(\d+)\s*(?:-\s*)?(.*)$/i;
const SEASON_SPECIAL = /^S(\d+)\s*-\s*(.+)$/i;
const escapeRegex = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const seasonEpisodes = new Map<number, SeasonEpisode[]>();
const seasonSpecials = new Map<number, Episode[]>();
const groupEpisodes = new Map<string, Episode[]>(groupConfigs.map((g) => [g.id, []]));
const unmatched: string[] = [];

function toEpisode(raw: RawEpisode, code: string | null, title: string, guest: string | null, herohero: boolean): Episode {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(raw.releaseDate)) fail("episodes.json", `"${raw.name}": invalid releaseDate "${raw.releaseDate}"`);
  return {
    spotifyId: raw.id,
    code,
    title,
    guest,
    description: raw.description,
    releaseDate: raw.releaseDate,
    durationMinutes: Math.round(raw.durationMs / 60000),
    image: raw.image,
    spotifyUrl: `https://open.spotify.com/episode/${raw.id}`,
    heroheroUrl: herohero ? profile.platforms.herohero : null,
  };
}

const push = <K, V>(map: Map<K, V[]>, key: K, value: V) => map.set(key, [...(map.get(key) ?? []), value]);
const splitGuest = (title: string) => (title.includes(" - ") ? title.slice(0, title.indexOf(" - ")).trim() : null);

for (const raw of rawEpisodes) {
  const ep = raw.name.match(SEASON_EPISODE);
  if (ep) {
    const season = Number(ep[1]);
    const number = Number(ep[2]);
    const code = `S${String(season).padStart(2, "0")}E${String(number).padStart(2, "0")}`;
    const title = ep[3].trim() || raw.name;
    const herohero = season >= seasonsJson.heroheroFromSeason;
    push(seasonEpisodes, season, { ...toEpisode(raw, code, title, splitGuest(title), herohero), number });
    continue;
  }
  const special = raw.name.match(SEASON_SPECIAL);
  if (special) {
    const season = Number(special[1]);
    const code = `S${String(season).padStart(2, "0")}`;
    push(seasonSpecials, season, toEpisode(raw, code, special[2].trim(), null, false));
    continue;
  }
  const group = groupConfigs.find((g) => g.prefix && new RegExp(`^${escapeRegex(g.prefix)}\\b`, "i").test(raw.name));
  if (group) {
    const m = raw.name.match(new RegExp(`^(${escapeRegex(group.prefix!)}\\s*#?\\s*\\d*)\\s*(?:-\\s*)?(.*)$`, "i"))!;
    push(groupEpisodes, group.id, toEpisode(raw, m[1].trim(), m[2].trim() || m[1].trim(), null, group.herohero));
    continue;
  }
  const fallback = fallbackGroups[0];
  if (!fallback) {
    unmatched.push(raw.name);
    continue;
  }
  push(groupEpisodes, fallback.id, toEpisode(raw, null, raw.name, null, fallback.herohero));
}

if (unmatched.length > 0)
  fail("groups.json", `episodes match no season or group (add a prefix group or a fallback): ${unmatched.join(", ")}`);

// ---- Seasons --------------------------------------------------------------------------------

const latestSeason = Math.max(...seasonEpisodes.keys(), ...seasonConfigs.keys());

export const seasons: Season[] = Array.from({ length: latestSeason }, (_, i) => latestSeason - i).map((number) => {
  const config = seasonConfigs.get(number);
  const episodes = (seasonEpisodes.get(number) ?? []).sort((a, b) => a.number - b.number);
  episodes.forEach((e, i) => {
    if (i > 0 && e.number === episodes[i - 1].number) fail("episodes.json", `duplicate episode ${e.code}`);
  });
  const plannedEpisodes = config?.plannedEpisodes ?? seasonsJson.defaultPlannedEpisodes;
  const isRunning = number === latestSeason && episodes.length < plannedEpisodes;
  return {
    number,
    episodes,
    specials: (seasonSpecials.get(number) ?? []).sort((a, b) => a.releaseDate.localeCompare(b.releaseDate)),
    plannedEpisodes,
    upcoming: isRunning ? plannedEpisodes - episodes.length : 0,
    isRunning,
    year: Number(
      [...episodes, ...(seasonSpecials.get(number) ?? [])]
        .map((e) => e.releaseDate)
        .sort()[0]
        ?.slice(0, 4) ?? new Date().getFullYear(),
    ),
    guests: episodes.map((e) => e.guest).filter((g): g is string => g !== null),
    youtubePlaylist: config?.youtubePlaylist ?? null,
  };
});

export const currentSeason: Season = seasons[0];

// Sponsorship is only ever shown for the current season; once a new season starts, a stale
// sponsorship.json (pointing at an older season) is simply not displayed until it is updated.
const sponsorship = sponsorshipJson as { season: number | null; partners: Partner[] };
sponsorship.partners.forEach((p, i) => {
  if (!p.name || !isUrl(p.url) || !p.logo) fail("sponsorship.json", `partners[${i}]: name, https url and logo are required`);
});
export const currentPartners: Partner[] = sponsorship.season === currentSeason.number ? sponsorship.partners : [];

// Groups keep the order from groups.json; empty groups are hidden.
export const groups: Group[] = groupConfigs
  .map((g) => ({
    id: g.id,
    title: g.title,
    description: g.description,
    chip: g.chip,
    herohero: g.herohero,
    episodes: groupEpisodes.get(g.id)!.sort((a, b) => b.releaseDate.localeCompare(a.releaseDate)),
    youtubePlaylist: g.youtubePlaylist ?? null,
  }))
  .filter((g) => g.episodes.length > 0);

/** Release date of the very first episode (ISO) */
export const firstReleaseDate: string = rawEpisodes.map((e) => e.releaseDate).sort()[0];

export const stats = {
  seasons: seasons.length,
  episodes: seasons.reduce((n, s) => n + s.episodes.length, 0),
  specials: seasons.reduce((n, s) => n + s.specials.length, 0),
  groupEpisodes: groups.reduce((n, g) => n + g.episodes.length, 0),
};
